/*
 * Main-process часть плагина (Vesktop). Импортировать сюда модули рендерера
 * (@webpack, @api и т.д.) ЗАПРЕЩЕНО — файл бандлится в main-процесс,
 * и импорты рендерера ломают сборку (см. историю бага «Cannot find module ~plugins»).
 */

import { spawn } from "child_process";
import { app, desktopCapturer, type IpcMainInvokeEvent } from "electron";
import { closeSync, mkdirSync, openSync, readFileSync, readSync, statSync, writeFileSync } from "fs";
import { constants as osConstants, setPriority } from "os";
import { join } from "path";

export interface P2PSourceInfo {
    /** Electron source id, например "screen:0:0" или "window:131076:0" */
    id: string;
    name: string;
    /** dataURL превью (png) или null, если кадр пустой */
    thumb: string | null;
    isScreen: boolean;
}

export interface P2PAudioStartResult {
    ok: boolean;
    error?: string;
}

/** Список источников захвата (экраны вперёд, затем окна) с превью для собственного пикера.
 *  ВАЖНО: Vencord вызывает native-функции как (IpcMainInvokeEvent, ...args) — первый
 *  аргумент ВСЕГДА event (см. папку src/plugins у Vencord: любые native.ts). Раньше мы объявляли
 *  getSources(width, height) без event-параметра: width = event-объект, height = 384,
 *  а thumbnailSize = { width: <event>, height: 384 } → gin-конверсия падала с
 *  «Error processing argument at index 2» и пикер навсегда оставался пустым. */
export async function getSources(_e: IpcMainInvokeEvent, width = 384, height = 216): Promise<P2PSourceInfo[]> {
    // страховка от нецелых/битых значений — gfx::Size требует строгие целые
    const w = Math.max(1, Math.floor(Number(width) || 384));
    const h = Math.max(1, Math.floor(Number(height) || 216));
    const sources = await desktopCapturer.getSources({
        types: ["window", "screen"],
        thumbnailSize: { width: w, height: h },
        fetchWindowIcons: true
    });

    const list: P2PSourceInfo[] = sources.map(s => ({
        id: s.id,
        name: s.name || (s.id.startsWith("screen:") ? "Экран" : "Окно"),
        thumb: s.thumbnail.isEmpty() ? null : s.thumbnail.toDataURL(),
        isScreen: s.id.startsWith("screen:")
    }));

    list.sort((a, b) => Number(b.isScreen) - Number(a.isScreen) || a.name.localeCompare(b.name));
    return list;
}

