    + "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
    + "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
    + "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";

let audioProc: ReturnType<typeof spawn> | null = null;
let audioQueue: Buffer[] = [];
let audioQueuedBytes = 0;
/** хелпер завершился ПОСЛЕ успешного старта (закрыли игру, краш, сменилось устройство) —
 *  вотчдог рендерера перезапустит его сам (v1.20: раньше звук молча исчезал до конца эфира) */
let audioProcDead = false;
/** Стерео-кадр float32 = 8 байт. Куски из пайпа приходят ПРОИЗВОЛЬНОЙ длины —
 *  отдаём рендереру только целые кадры, хвост ждёт следующего куска. Раньше
 *  невыровненный хвост сдвигал все следующие сэмплы: вместо звука — шум. */
const FRAME_BYTES = 8;
/** ~0.5 с звука float32 стерео (384000 Б/с) — защита от переполнения */
const AUDIO_QUEUE_CAP = 192_000;

function audioHelperDir(): string {
    return join(app.getPath("userData"), "p2pstream");
}

/** Распаковать хелпер. true — exe готов (валидный MZ-заголовок) */
function extractAudioHelper(force = false): boolean {
    try {
        const dir = audioHelperDir();
        mkdirSync(dir, { recursive: true });
        const exePath = join(dir, "p2paudio.exe");
        const buf = Buffer.from(P2P_AUDIO_EXE_B64, "base64");
        let needWrite = force;
        if (!needWrite) {
            try {
                needWrite = !readFileSync(exePath).equals(buf);
            } catch {
                needWrite = true;
            }
        }
        if (needWrite) writeFileSync(exePath, buf);
        // контроль целостности: если файл начинается не с MZ — перезаписываем принудительно
        const fd = statSync(exePath);
        if (fd.size === buf.length) {
            const head = readFileSyncRange(exePath, 2);
            if (head !== "MZ") {
                writeFileSync(exePath, buf);
            }
        }
        return true;
    } catch {
        return false;
    }
}

function readFileSyncRange(path: string, n: number): string {
    try {
        const fd = openSync(path, "r");
        const buf = Buffer.alloc(n);
        try { readSync(fd, buf, 0, n, 0); } finally { closeSync(fd); }
        return buf.toString("latin1");
    } catch {
        return "";
    }
}

function audioHelperPath(): string {
    const dir = audioHelperDir();
    mkdirSync(dir, { recursive: true });
    const exePath = join(dir, "p2paudio.exe");
    const buf = Buffer.from(P2P_AUDIO_EXE_B64, "base64");
    // сравниваем СОДЕРЖИМОЕ, а не размер: новая сборка того же размера
    // раньше не перезаписывала старый (сломанный) exe на диске
    let same = false;
    try { same = readFileSync(exePath).equals(buf); } catch { /* нет файла */ }
    if (!same) writeFileSync(exePath, buf);
    return exePath;
}

function stopAudioInternal(): void {
    const proc = audioProc;
    audioProc = null;
    audioQueue = [];
    audioQueuedBytes = 0;
    audioProcDead = false;
    if (proc) {
        try { proc.kill(); } catch { /* ignore */ }
    }
}

/** hwnd из Electron source id "window:<hwnd>:<index>" */
function hwndFromSourceId(id: string): string | null {
    const m = /^window:(\d+):/.exec(id ?? "");
    return m ? m[1] : null;
}

/**
 * Запустить нативный захват звука. mode:
 *   include-window — звук окна (id = Electron source id окна, hwnd -> pid);
 *   exclude-tree   — вся система, кроме дерева процесса Discord (main-процесс = process.pid).
 * Резолвится после "READY" от хелпера (до 4 с) либо с ошибкой.
 */
export async function startAudio(_e: IpcMainInvokeEvent, opts: { mode: string; id?: string }): Promise<P2PAudioStartResult> {
    stopAudioInternal();

    const mode = String(opts?.mode ?? "");
    const id = String(opts?.id ?? "");
    let args: string[];
    if (mode === "include-window") {
        const hwnd = hwndFromSourceId(id);
        if (!hwnd) return { ok: false, error: "источник не является окном" };
        args = ["include-hwnd", hwnd];
    } else if (mode === "exclude-tree") {
        args = ["exclude-pid", String(process.pid)];
    } else {
        return { ok: false, error: `неизвестный режим: ${mode}` };
    }

    let exePath: string;
    try {
        exePath = audioHelperPath();
    } catch (e) {
        return { ok: false, error: `не удалось распаковать хелпер: ${e}` };
    }

    // спавн с ретраями: сразу после записи exe может быть залочен антивирусом
    // (Windows Defender сканирует свежий exe) — ошибка UNKNOWN/EACCES/EPERM.
    let proc: ReturnType<typeof spawn> | null = null;
    let spawnError: Error | null = null;
    for (let attempt = 1; attempt <= 3; attempt++) {
        try {
            proc = spawn(exePath, args, { stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
            spawnError = null;
            break;
        } catch (e: any) {
            spawnError = e;
            if (attempt < 3) {
                // перезаписываем exe (вдруг он битый от прошлой версии) и ждём снятия блокировки
                try { extractAudioHelper(true); } catch { /* ignore */ }
                await new Promise(r => setTimeout(r, 350));
            }
        }
    }
    if (!proc) {
        return { ok: false, error: `не удалось запустить хелпер: ${spawnError}` };
    }
    audioProc = proc;
    // под нагрузкой игры хелпер с обычным приоритетом может притормаживать (рывки подачи звука)
    try { if (proc.pid) setPriority(proc.pid, osConstants.priority.PRIORITY_ABOVE_NORMAL); } catch { /* нет прав — не критично */ }
    audioQueue = [];
    audioQueuedBytes = 0;
    audioProcDead = false;

    return await new Promise<P2PAudioStartResult>(resolve => {
        let settled = false;
        let stderrTail = "";

        const finish = (res: P2PAudioStartResult) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve(res);
        };

        const timer = setTimeout(() => {
            stopAudioInternal();
            finish({ ok: false, error: stderrTail || "хелпер не ответил READY" });
        }, 4000);

        proc.on("error", err => {
            finish({ ok: false, error: `spawn: ${err.message}` });
        });
        proc.on("exit", code => {
            finish({ ok: false, error: stderrTail || `хелпер завершился (код ${code})` });
        });

        proc.stdout?.on("data", (chunk: Buffer) => {
            if (audioProc !== proc) return;
            audioQueue.push(chunk);
            audioQueuedBytes += chunk.length;
            if (audioQueuedBytes > AUDIO_QUEUE_CAP) {
                // переполнение (рендерер не забирает): выбрасываем самое старое,
                // сохраняя выравнивание по кадрам
                const all = Buffer.concat(audioQueue);
                let keep = AUDIO_QUEUE_CAP / 2;
                keep -= keep % FRAME_BYTES;
                const tailStart = all.length - keep - ((all.length - keep) % FRAME_BYTES);
                audioQueue = [all.subarray(Math.max(0, tailStart))];
                audioQueuedBytes = audioQueue[0].length;
            }
        });

        // stderr построчно: кусок может содержать несколько строк или половину строки
        let stderrBuf = "";
        proc.stderr?.on("data", (chunk: Buffer) => {
            stderrBuf += chunk.toString("utf8");
            const lines = stderrBuf.split(/\r?\n/);
            stderrBuf = lines.pop() ?? "";
            for (const raw of lines) {
                const line = raw.trim();
                if (!line) continue;
                stderrTail = line.slice(0, 300);
                if (line === "READY") {
                    proc.removeAllListeners("exit");
                    proc.on("exit", () => {
                        // смерть хелпера после READY — штатная ситуация (закрыли игру,
                        // сменилось устройство): помечаем, вотчдог рендерера перезапустит.
                        audioProcDead = true;
                        if (audioProc === proc) stopAudioInternal();
                    });
                    proc.stdout?.on("close", () => {
                        if (audioProc === proc) audioProcDead = true;
                    });
                    finish({ ok: true });
                } else if (line.startsWith("ERR ")) {
                    finish({ ok: false, error: line.slice(4) });
                }
            }
        });
    });
}

/** Забрать накопившийся PCM (float32 LE 48k stereo) с прошлого вызова. */
export async function pullAudio(): Promise<Uint8Array | null> {
    if (!audioProc || audioQueue.length === 0) return null;
    const buf = audioQueue.length === 1 ? audioQueue[0] : Buffer.concat(audioQueue);
    const whole = buf.length - (buf.length % FRAME_BYTES);
    // неполный кадр остаётся в очереди до следующего куска из пайпа
    audioQueue = whole < buf.length ? [buf.subarray(whole)] : [];
    audioQueuedBytes = buf.length - whole;
    if (!whole) return null;
    return new Uint8Array(buf.buffer, buf.byteOffset, whole);
}

/** Остановить нативный захват звука. */
export async function stopAudio(): Promise<void> {
    stopAudioInternal();
}

/** Состояние хелпера для вотчдога рендерера (v1.20): мёртв ли процесс захвата */
export async function audioStatus(): Promise<{ dead: boolean; hasProc: boolean }> {
    return { dead: audioProcDead, hasProc: audioProc != null };
}

/**
 * Временные учётные данные Cloudflare TURN. Запрос идёт из main-процесса:
 * в рендерере Discord он упёрся бы в CSP (connect-src).
 */
export async function cfTurnIce(_e: IpcMainInvokeEvent, keyId: string, token: string): Promise<{ ok: boolean; iceServers?: unknown; error?: string; }> {
    try {
        const id = String(keyId ?? "").trim();
        const tok = String(token ?? "").trim();
        if (!id || !tok) return { ok: false, error: "не заданы Key ID / API token" };
        const res = await fetch(`https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(id)}/credentials/generate-ice-servers`, {
            method: "POST",
            headers: { "Authorization": `Bearer ${tok}`, "Content-Type": "application/json" },
            body: JSON.stringify({ ttl: 86400 })
        });
        const text = await res.text();
        if (!res.ok) return { ok: false, error: `HTTP ${res.status}: ${text.slice(0, 200)}` };
        return { ok: true, iceServers: JSON.parse(text)?.iceServers };
    } catch (e: any) {
        return { ok: false, error: String(e?.message ?? e) };
    }
}
// endregion

// Распаковываем хелпер сразу при загрузке main-части: к моменту старта эфира
// exe уже лежит на диске (антивирус успевает просканировать, спавн не ловит блокировку).
try {
    extractAudioHelper(false);
} catch { /* при старте аудио повторим */ }
